<script setup>
import {ref,computed,onMounted} from 'vue';
const token=ref(''), connected=ref(false), busy=ref(false),error=ref(''),notice=ref(''),tab=ref('Consejo');
const catalog=ref({expert:[],board:[],project:[],session:[],context:[],skill:[],artifact:[],repository:[],connection:[]});
const project=ref(null),board=ref(null),session=ref(null),transcript=ref([]),question=ref(''),title=ref(''),text=ref(''),scope=ref('SESSION'),consent=ref(false),selectedExperts=ref([]),file=ref(null),result=ref('');
const retention=ref(24),memoryScope=ref('project'),memoryConsent=ref(false),memoryText=ref('');
const expertName=ref(''),specialty=ref(''),principles=ref(''),skillIds=ref([]),repoPath=ref(''),repoId=ref(null),search=ref(''),connection=ref(null),connectionName=ref(''),connectionUrl=ref(''),readTools=ref(''),writeTools=ref(''),artifactKind=ref('requirement'),criteria=ref(''),target=ref('codex');
const relevantSessions=computed(()=>catalog.value.session.filter(s=>s.project_id===project.value));
const relevantArtifacts=computed(()=>catalog.value.artifact.filter(a=>a.project_id===project.value));
const activeContexts=computed(()=>catalog.value.context.filter(c=>c.session_id===session.value));
const activeBoard=computed(()=>catalog.value.board.find(b=>b.id===board.value));
async function api(path,body,method){const r=await fetch('/api'+path,{method:method||(body?'POST':'GET'),headers:{Authorization:'Bearer '+token.value,...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined});const d=await r.json();if(!r.ok)throw Error(typeof d.detail==='string'?d.detail:JSON.stringify(d.detail));return d;}
async function action(fn){busy.value=true;error.value='';notice.value='';try{await fn();}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function refresh(){catalog.value=await api('/catalog');board.value ||= catalog.value.board[0]?.id;project.value ||= catalog.value.project[0]?.id;}
async function login(){await action(async()=>{await refresh();connected.value=true;});}
async function loadSession(){if(session.value){transcript.value=await api('/sessions/'+session.value+'/messages');const s=catalog.value.session.find(s=>s.id===session.value);board.value=s.board_id;}}
async function newProject(){await action(async()=>{const p=await api('/projects',{name:title.value,description:text.value});project.value=p.id;title.value='';text.value='';await refresh();});}
async function newSession(){await action(async()=>{const s=await api('/sessions',{board_id:board.value,project_id:project.value,title:title.value||'Nueva discusión'});session.value=s.id;transcript.value=[];await refresh();});}
async function send(){await action(async()=>{transcript.value=await api('/sessions/'+session.value+'/turns',{text:question.value,max_turns:5});question.value='';});}
async function context(){await action(async()=>{const c=await api('/contexts',{session_id:session.value,title:title.value,text:text.value,scope:scope.value,permanent_consent:consent.value,expert_ids:selectedExperts.value,retention_hours:Number(retention.value)});if(file.value){const f=file.value;const u=await api('/contexts/'+c.id+'/upload?content_type='+encodeURIComponent(f.type||'text/plain'),{});const form=new FormData();Object.entries(u.fields).forEach(([k,v])=>form.append(k,v));form.append('file',f);const r=await fetch(u.url,{method:'POST',body:form});if(!r.ok)throw Error('No se pudo cargar el archivo en Spaces');await api('/contexts/'+c.id+'/finalize',{});}title.value='';text.value='';file.value=null;await refresh();notice.value='Contexto registrado';});}
async function createExpert(){await action(async()=>{await api('/experts',{name:expertName.value,specialty:specialty.value,principles:principles.value,skill_ids:skillIds.value});await refresh();notice.value='Experto creado';});}
async function createBoard(){await action(async()=>{await api('/boards',{name:title.value,mission:text.value,expert_ids:selectedExperts.value});await refresh();notice.value='Board creado';});}
async function skill(){await action(async()=>{await api('/skills',{name:title.value,content:text.value});await refresh();notice.value='Skill versionado';});}
async function artifact(){await action(async()=>{await api('/artifacts',{project_id:project.value,session_id:session.value,kind:artifactKind.value,title:title.value,content:text.value,acceptance_criteria:criteria.value.split('\n').filter(Boolean)});await refresh();notice.value='Borrador creado';});}
async function approve(a){await action(async()=>{await api('/artifacts/'+a.id+'/approve',{});await refresh();});}
async function exportPrompt(){await action(async()=>{result.value=(await api('/projects/'+project.value+'/export?target='+target.value)).prompt;});}
async function addRepo(){await action(async()=>{await api('/repositories',{project_id:project.value,path:repoPath.value});await refresh();});}
async function reviewRepo(){await action(async()=>{const r=await api('/projects/'+project.value+'/review',{repository_id:repoId.value,query:search.value});result.value=r.report;});}
async function inspectRepo(){await action(async()=>{result.value=JSON.stringify(await api('/repositories/'+repoId.value+'/inspect?query='+encodeURIComponent(search.value)),null,2);});}
async function addConnection(){await action(async()=>{await api('/connections',{name:connectionName.value,url:connectionUrl.value,expert_ids:selectedExperts.value,read_tools:readTools.value.split(',').map(s=>s.trim()).filter(Boolean),write_tools:writeTools.value.split(',').map(s=>s.trim()).filter(Boolean)});await refresh();});}
async function discover(){await action(async()=>{result.value=JSON.stringify(await api('/connections/'+connection.value+'/tools'),null,2);});}
async function generateDraft(){await action(async()=>{await api('/sessions/'+session.value+'/draft',{kind:artifactKind.value});await refresh();notice.value='Borrador generado para tu revisión';});}
function memoryTarget(){return memoryScope.value==='personal'?null:memoryScope.value==='project'?project.value:memoryScope.value==='board'?board.value:selectedExperts.value[0];}
async function saveMemory(){await action(async()=>{await api('/memories',{scope:memoryScope.value,target_id:memoryTarget(),text:memoryText.value,approved:memoryConsent.value});notice.value='Memoria aprobada incorporada';memoryText.value='';memoryConsent.value=false;});}
async function searchMemory(){await action(async()=>{result.value=JSON.stringify(await api('/memories/search',{scope:memoryScope.value,target_id:memoryTarget(),query:memoryText.value}),null,2);});}
async function importSkill(event){const f=event.target.files[0];if(!f)return;await action(async()=>{const form=new FormData();form.append('name',title.value||f.name);form.append('file',f);const r=await fetch('/api/skills/import',{method:'POST',headers:{Authorization:'Bearer '+token.value},body:form});if(!r.ok)throw Error('No se pudo importar el Skill');await refresh();notice.value='Skill importado';});}
function download(){const u=URL.createObjectURL(new Blob([result.value],{type:'text/markdown'}));const a=document.createElement('a');a.href=u;a.download='vitruvius-development-prompt.md';a.click();URL.revokeObjectURL(u);}
</script>
<template>
<v-app><div class="shell"><aside><div class="brand">V<span>ITRUVIUS</span></div><p class="tagline">Think. Debate. Design. Decide.</p><nav aria-label="Navegación principal"><button v-for="item in ['Consejo','Contexto','Memoria','Expertos','Skills','Decisiones','Repositorios','Conexiones']" :class="{active:tab===item}" @click="tab=item;result=''">{{item}}</button></nav><div class="sidebar-bottom">Tu consejo personal<br><small>Un espacio privado de criterio.</small></div></aside><main>
<header><div><p class="eyebrow">PERSONAL EXPERT COUNCIL</p><h1>{{tab==='Consejo'?'Las buenas decisiones empiezan conversando.':tab}}</h1></div><v-chip color="secondary" variant="tonal">{{connected?'Sesión privada':'Acceso del propietario'}}</v-chip></header>
<v-alert v-if="error" type="error" class="mb-5" closable @click:close="error=''">{{error}}</v-alert><v-alert v-if="notice" type="success" class="mb-5">{{notice}}</v-alert>
<v-card v-if="!connected" class="login" rounded="xl"><h2>Bienvenido a Vitruvius</h2><p class="muted">Introduce tu token de propietario para abrir el espacio de trabajo.</p><v-text-field v-model="token" label="Token de acceso" type="password" autocomplete="off" @keyup.enter="login"/><v-btn color="primary" @click="login" :loading="busy">Abrir mi espacio</v-btn><p class="muted mt-5">El token se conserva solo durante esta visita. El servicio necesita PostgreSQL para iniciar una sesión.</p></v-card>
<template v-else><div class="workspace"><v-select v-model="project" :items="catalog.project" item-title="name" item-value="id" label="Proyecto" @update:model-value="session=null;transcript=[]"/><v-select v-model="board" :items="catalog.board" item-title="name" item-value="id" label="Board"/><v-select v-model="session" :items="relevantSessions" item-title="title" item-value="id" label="Sesión" @update:model-value="loadSession"/></div><v-btn class="mb-5" variant="text" @click="project=null;session=null;transcript=[];tab='Consejo'">Crear otro proyecto</v-btn>
<section v-if="tab==='Consejo'">
<div class="panelists"><div v-for="e in catalog.expert.filter(e=>activeBoard?.expert_ids.includes(e.id))" class="panelist"><div class="avatar">{{e.name.split(' ').map(s=>s[0]).slice(0,2).join('')}}</div><strong>{{e.name}}</strong><small>{{e.specialty}}</small></div></div><p class="identity">Panelistas virtuales inspirados en especialidades de autores. No son las personas reales. Las bibliotecas empiezan vacías: solo se citan fuentes incorporadas y recuperadas.</p>
<div class="conversation"><div v-if="!session" class="empty"><p class="eyebrow">TU PRÓXIMA IDEA, EN BUENAS MANOS</p><h2>Convoca al consejo.</h2><p>Comparte el problema, contrasta perspectivas y convierte los acuerdos en una especificación.</p><v-text-field v-model="title" label="Nombre del proyecto o de la sesión"/><v-textarea v-model="text" label="Descripción del nuevo proyecto (opcional)" rows="2"/><v-btn v-if="!project" color="primary" @click="newProject" :disabled="!title||busy">Crear proyecto</v-btn><v-btn v-else color="primary" @click="newSession" :disabled="!board||busy">Iniciar discusión</v-btn></div>
<article v-for="m in transcript" :class="['message',{owner:m.speaker==='Propietario'}]"><div class="speaker">{{m.speaker}}</div><div class="message-body">{{m.content}}</div><small v-for="c in m.citations" class="citation">{{c.title}} · {{c.page?'p. '+c.page:'fragmento'}} · {{c.chunk_id}}</small></article><div v-if="session&&!transcript.length" class="empty"><h2>¿Qué vamos a diseñar?</h2><p>El consejo puede cuestionar supuestos, comparar alternativas y pedirte información.</p></div></div>
<div v-if="session" class="composer"><v-textarea v-model="question" label="Comparte tu necesidad o responde al consejo" rows="3" hide-details/><v-btn color="primary" :loading="busy" :disabled="!question" @click="send">Consultar al consejo</v-btn><v-btn variant="text" @click="session=null;transcript=[]">Nueva sesión</v-btn></div>
</section>
<section v-if="tab==='Contexto'" class="two-col"><v-card class="form-card"><h2>Contexto con límites claros</h2><p class="muted">Por defecto expira en 24 horas. No se convierte automáticamente en conocimiento ni memoria.</p><v-text-field v-model="title" label="Título"/><v-textarea v-model="text" label="Texto adicional"/><v-text-field v-model="retention" type="number" min="1" max="720" label="Retención temporal (horas)"/><v-select v-model="scope" :items="['REQUEST','SESSION','PROJECT','BOARD','EXPERT','GLOBAL']" label="Alcance"/><v-select v-model="selectedExperts" :items="catalog.expert" item-title="name" item-value="id" multiple label="Expertos (vacío: todo el Board)"/><v-checkbox v-if="!['REQUEST','SESSION'].includes(scope)" v-model="consent" label="Autorizo conservar este conocimiento"/><label class="file-label">Archivo PDF, texto o Markdown (máximo 20 MB)<input type="file" accept=".pdf,.txt,.md" @change="file=$event.target.files[0]"/></label><v-btn color="primary" @click="context" :disabled="!session||!title||busy">Añadir contexto</v-btn></v-card><div><v-card v-for="c in activeContexts" class="record-card"><h3>{{c.title}}</h3><v-chip size="small">{{c.scope}} · {{c.status}}</v-chip><p>{{c.expires_at?'Expira: '+new Date(c.expires_at).toLocaleString():'Conservación permanente autorizada'}}</p><v-btn size="small" variant="text" @click="action(async()=>{await api('/contexts/'+c.id,undefined,'DELETE');await refresh()})">Eliminar</v-btn><v-btn v-if="c.expires_at" size="small" variant="text" @click="action(async()=>{await api('/contexts/'+c.id+'/promote?scope=PROJECT',{});await refresh()})">Conservar en proyecto</v-btn></v-card></div></section>
<section v-if="tab==='Memoria'" class="two-col"><v-card class="form-card"><h2>Lo que merece recordarse</h2><p class="muted">La memoria de largo plazo se incorpora solo por tu autorización. El contexto temporal permanece separado.</p><v-select v-model="memoryScope" :items="['personal','project','board','expert']" label="Ámbito de memoria"/><v-select v-if="memoryScope==='expert'" v-model="selectedExperts" :items="catalog.expert" item-title="name" item-value="id" multiple label="Experto (se usa el primero seleccionado)"/><v-textarea v-model="memoryText" label="Conclusión aprobada o consulta de memoria" rows="8"/><v-checkbox v-model="memoryConsent" label="Apruebo incorporar este texto a la memoria permanente"/><v-btn color="primary" @click="saveMemory" :disabled="busy||!memoryConsent||!memoryText">Guardar memoria aprobada</v-btn><v-btn class="mt-3" variant="text" @click="searchMemory" :disabled="busy||!memoryText">Buscar recuerdos</v-btn></v-card><v-card class="form-card"><h2>Continuidad con criterio</h2><div v-for="m in catalog.memory_event" class="record-card"><p>Memoria {{m.scope}} · aprobada</p><v-btn size="small" variant="text" @click="action(async()=>{await api('/memories/'+m.id,undefined,'DELETE');await refresh()})">Eliminar episodio</v-btn></div><p>Los panelistas recuperan recuerdos del proyecto, del Board, del experto y de tus preferencias personales. Una hipótesis de una discusión no se convierte por sí sola en un hecho.</p><p class="muted">Los adjuntos temporales se eliminan según su retención. Las respuestas que los citan permanecen en el historial de la sesión hasta eliminarlo.</p></v-card></section>
<section v-if="tab==='Expertos'" class="two-col"><v-card class="form-card"><h2>Construir un experto</h2><v-text-field v-model="expertName" label="Nombre persistente"/><v-text-field v-model="specialty" label="Especialidad"/><v-textarea v-model="principles" label="Principios y método"/><v-select v-model="skillIds" :items="catalog.skill" item-title="name" item-value="id" multiple label="Skills"/><v-btn color="primary" @click="createExpert" :disabled="busy||!expertName||!specialty">Crear experto</v-btn></v-card><v-card class="form-card"><h2>Constituir un Board</h2><v-text-field v-model="title" label="Nombre del Board"/><v-textarea v-model="text" label="Misión"/><v-select v-model="selectedExperts" :items="catalog.expert" item-title="name" item-value="id" multiple label="Panelistas"/><v-btn color="primary" @click="createBoard" :disabled="busy||!title||!selectedExperts.length">Crear Board</v-btn></v-card></section>
<section v-if="tab==='Skills'" class="two-col"><v-card class="form-card"><h2>Registrar Skill</h2><label class="file-label">Importar SKILL.md o ZIP<input type="file" accept=".md,.zip" @change="importSkill"/></label><v-text-field v-model="title" label="Nombre"/><v-textarea v-model="text" label="Contenido de SKILL.md" rows="12"/><v-btn color="primary" @click="skill" :disabled="busy||!title||!text">Guardar versión</v-btn></v-card><div><v-card v-for="s in catalog.skill" class="record-card"><h3>{{s.name}} <small>v{{s.version}}</small></h3><p class="pre">{{s.content}}</p></v-card></div></section>
<section v-if="tab==='Decisiones'" class="two-col"><v-card class="form-card"><h2>De la discusión al acuerdo</h2><v-btn class="mb-5" @click="generateDraft" :disabled="busy||!session">Proponer borrador desde la discusión</v-btn><v-select v-model="artifactKind" :items="['requirement','adr','specification']" label="Tipo"/><v-text-field v-model="title" label="Título"/><v-textarea v-model="text" label="Especificación y alternativas" rows="8"/><v-textarea v-model="criteria" label="Criterios de aceptación (uno por línea)"/><v-btn color="primary" @click="artifact" :disabled="busy||!session||!title||!text||!criteria">Guardar borrador</v-btn></v-card><div><v-card v-for="a in relevantArtifacts" class="record-card"><v-chip size="small" :color="a.status==='approved'?'secondary':'primary'">{{a.status==='approved'?'Aprobado':'Borrador'}} · {{a.kind}} · v{{a.version}}</v-chip><h3>{{a.title}}</h3><p class="pre">{{a.content}}</p><ul><li v-for="c in a.acceptance_criteria">{{c}}</li></ul><v-btn v-if="a.status!=='approved'" class="mt-4" @click="approve(a)" :disabled="busy">Aprobar esta versión</v-btn></v-card><v-card class="form-card"><h3>Entregar a desarrollo</h3><p>La exportación exige aprobar las versiones actuales.</p><v-select v-model="target" :items="['codex','claude-code']" label="Destino"/><v-btn color="primary" @click="exportPrompt" :disabled="busy||!project">Generar prompt</v-btn></v-card></div></section>
<section v-if="tab==='Repositorios'" class="two-col"><v-card class="form-card"><h2>Inteligencia de código</h2><p class="muted">Consultas de solo lectura sobre repositorios montados por el propietario. No ejecuta código del proyecto.</p><v-text-field v-model="repoPath" label="Ruta autorizada: /repositories/nombre"/><v-btn @click="addRepo" :disabled="busy||!project||!repoPath">Vincular repositorio</v-btn></v-card><v-card class="form-card"><v-select v-model="repoId" :items="catalog.repository" item-title="path" item-value="id" label="Repositorio"/><v-text-field v-model="search" label="Buscar texto (vacío: listar archivos)"/><v-btn color="primary" @click="inspectRepo" :disabled="busy||!repoId">Consultar código</v-btn><v-btn class="mt-3" variant="text" @click="reviewRepo" :disabled="busy||!repoId||!search">Revisar contra acuerdos aprobados</v-btn></v-card></section>
<section v-if="tab==='Conexiones'" class="two-col"><v-card class="form-card"><h2>Herramientas MCP</h2><p class="muted">El propietario debe autorizar previamente el origen HTTPS en el servidor. Las acciones de escritura requieren una aprobación para los argumentos exactos.</p><v-text-field v-model="connectionName" label="Nombre"/><v-text-field v-model="connectionUrl" label="URL HTTPS del servidor MCP"/><v-select v-model="selectedExperts" :items="catalog.expert" item-title="name" item-value="id" multiple label="Expertos autorizados"/><v-text-field v-model="readTools" label="Herramientas de lectura, separadas por coma"/><v-text-field v-model="writeTools" label="Herramientas de escritura, separadas por coma"/><v-btn @click="addConnection" :disabled="busy||!connectionName||!connectionUrl">Registrar conexión</v-btn></v-card><v-card class="form-card"><h2>Descubrir herramientas</h2><div v-for="r in catalog.tool_request" class="record-card"><h3>{{r.tool}}</h3><p>Revisa los argumentos antes de autorizar la acción.</p><pre>{{JSON.stringify(r.arguments,null,2)}}</pre><v-btn color="primary" @click="action(async()=>{result=JSON.stringify(await api('/tool-requests/'+r.id+'/execute',{}),null,2);await refresh()})" :disabled="busy">Aprobar y ejecutar estos argumentos</v-btn></div><v-select v-model="connection" :items="catalog.connection" item-title="name" item-value="id" label="Conexión"/><v-btn color="primary" @click="discover" :disabled="busy||!connection">Consultar servidor</v-btn><p class="muted mt-5">MCP entrante: /mcp/ · Autenticación Bearer del propietario. La compatibilidad depende de las capacidades del cliente.</p></v-card></section>
<v-card v-if="result" class="form-card mt-6"><div class="result-header"><h2>Resultado</h2><v-btn @click="download">Descargar</v-btn></div><pre>{{result}}</pre></v-card>
</template><footer>VITRUVIUS · Las conclusiones son propuestas hasta que tú las apruebes.</footer></main></div></v-app>
</template>
